<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\TenantLoginProviderTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait TenantLoginProviderTenantAccessor
{
    private TenantLoginProviderTenantVO $_tenant;
    public function getTenant(): TenantRef
    {
        return $this->_tenant->value();
    }
    public function tenant(): TenantLoginProviderTenantVO
    {
        return $this->_tenant;
    }
    public function isTenantChanged(?self $original = null): bool
    {
        return !$this->_tenant->equals($original?->_tenant);
    }
    public function withTenant(TenantLoginProviderTenantVO|TenantRef $tenant): self
    {
        $copy = clone $this;
        $copy->_tenant = TenantLoginProviderTenantVO::from($tenant);
        return $copy;
    }
}
